mapper.select:
select user_id , mac_adr , os_cd , version , app_os_ver , app_nm , last_access_dt , auto_login_yn , bio_login_yn , apv_sttus_cd , bio_login_token from msf_usr_app_info where 1=1 and uuid = #{uuid}
and apv_sttus_cd = 'A'
order by amd_dt desc

mapper.update:
update msf_usr_app_info
set cret_id = cret_id

  , app_nm = #{appNm}


  , apv_sttus_cd = #{apvSttusCd}


  , auto_login_yn = #{autoLoginYn}


  , bio_login_yn = #{bioLoginYn}


  , os_cd = #{osCd}


  , version = #{version}


  , app_os_ver = #{appOsVer}


  , bio_login_token = #{bioLoginToken}

where 1=1
and uuid = #{deviceUuid}
and user_id = #{userId}

UPDATE msf_usr_app_token_txn
SET token_valid_period = 'EXPIRED'
WHERE app_token_seq = (
  SELECT app_token_seq
  FROM msf_usr_app_token_txn
  WHERE uuid = #{deviceUuid}
  AND user_id = #{userId}
  ORDER BY cret_dt DESC
  LIMIT 1
)
